import urllib.parse

BASE_URL = "https://www.linkedin.com/jobs/search/"

EXPERIENCE_LEVELS = {
    "internship": "1",
    "entry level": "2",
    "associate": "3",
    "mid-senior": "4",
    "director": "5",
    "executive": "6",
}

JOB_TYPES = {
    "full-time": "F",
    "part-time": "P",
    "contract": "C",
    "temporary": "T",
    "volunteer": "V",
    "internship": "I",
    "other": "O",
}

WORKPLACE_TYPES = {
    "on-site": "1",
    "remote": "2",
    "hybrid": "3",
}

DATE_POSTED_PRESETS = {
    "day": "r86400",
    "week": "r604800",
    "month": "r2592000",
    "any": None,
}

SORT_BY = {
    "relevance": "R",
    "date": "DD",
}


def resolve_posted(value):
    if not value:
        return None
    key = str(value).strip().lower()
    if key in DATE_POSTED_PRESETS:
        return DATE_POSTED_PRESETS[key]
    try:
        hours = float(key)
    except ValueError:
        return None
    if hours <= 0:
        return None
    return f"r{int(hours * 3600)}"


def codes_from_list(values, mapping):
    if not values:
        return None
    codes = []
    for v in values:
        key = str(v).strip().lower()
        if key in mapping:
            codes.append(mapping[key])
    return ",".join(codes) if codes else None


f = _json
record_id = f.get("id")
params = {}

if f.get("Keywords"):
    params["keywords"] = f["Keywords"]
if f.get("Location"):
    params["location"] = f["Location"]

exp = codes_from_list(f.get("Experience Level"), EXPERIENCE_LEVELS)
if exp:
    params["f_E"] = exp

jt = codes_from_list(f.get("Job Type"), JOB_TYPES)
if jt:
    params["f_JT"] = jt

wt = codes_from_list(f.get("Workplace Type"), WORKPLACE_TYPES)
if wt:
    params["f_WT"] = wt

tpr = resolve_posted(f.get("Date Posted"))
if tpr:
    params["f_TPR"] = tpr

sort_key = str(f.get("Sort By") or "relevance").strip().lower()
params["sortBy"] = SORT_BY.get(sort_key, "R")

if f.get("Distance"):
    params["distance"] = f["Distance"]

if f.get("Company ID"):
    params["f_C"] = f["Company ID"]

if f.get("Easy Apply"):
    params["f_AL"] = "true"

query = urllib.parse.urlencode(params, quote_via=urllib.parse.quote)
url = f"{BASE_URL}?{query}" if query else BASE_URL

return {
    "json": {
        "id": record_id,
        "Generated URL": url
    }
}
